function controlNotice(){return `<div class="card"><div class="hint v1012-help">${unifiedMode()?`<b>کنترل یکپارچه کل رایو (تک‌انبار)</b><br>در این حالت، همه موجودی عملیاتی در انبار اصلی مدیریت می‌شود. ورود، مصرف فروش و ضایعات ثبت می‌شوند و نیازی به ثبت انتقال داخلی نیست.${controlActivationDate()}<br><b>موجودی = آخرین شمارش هر قلم + ورود به انبار − مصرف فروش − پرتی و ضایعات</b><br>فاکتورهای خرید و گزارش صندوق روی موجودی اثری ندارند. فروش آیتم‌ها، پرتی و ضایعات را می‌توانید روزانه، هفتگی یا یکجا ثبت کنید؛ در انبارگردانی بعدی، اختلاف هر قلم به‌عنوان مغایرت همان دوره ثبت می‌شود. <a href="inventory.html?tab=count">انبارگردانی و مغایرت</a>`:`<b>کنترل تفکیکی محل‌ها</b><br>برای کنترل کل رایو، افتتاحیه کل، ورود خریدهای تحویل‌شده، فروش آیتم‌ها، ضایعات و مصرف‌های خارج از فروش را ثبت کنید. انتقال بین محل‌ها اختیاری است. در پایان دوره تمام موجودی مجموعه را شمارش کنید. مواد مصرف‌شده در فروش را دوباره خروج دستی نزنید.<br>بدون ثبت کامل انتقال‌ها، مانده و مسئولیت کسری هر سکشن قابل اتکای قطعی نیست. <a href="inventory.html?tab=settings">تنظیم حالت و افتتاحیه</a>`}</div></div>`}
function controlSettingsPane(){return `<div class="card"><h2>شروع دوباره انبارداری از یک تاریخ</h2><p class="hint">برای شروع تازه: همه سوابق انبار با تاریخ قبل از تاریخ شروع (شمارش و انبارگردانی، موجودی اولیه، ورود به انبار، گردش‌ها، فروش، پرتی و ضایعات، مصرف پرسنلی، شمارش مصرفی‌ها و کنترل روزانه نوشیدنی) باطل می‌شوند و آخرین قیمت خرید اقلامی که قیمتشان قبل از این تاریخ ثبت شده صفر می‌شود. فهرست مواد اولیه، رسپی‌ها، فاکتورهای خرید و پرداخت‌ها دست نمی‌خورند. پیش‌نمایش، پشتیبان اجباری و بازگردانی دارد. بعد از اجرا، شمارش افتتاحیه همان تاریخ را ثبت کنید.</p><div class="form-grid"><div class="field"><label>تاریخ شروع</label><input id="rayoFreshDate" data-jalali="1" value=""></div></div><div class="v1012-actions"><button class="btn btn-danger" onclick="RayoInventoryV10.openStartFresh()">پیش‌نمایش شروع دوباره</button><button class="btn" onclick="RayoInventoryV10.openStartFreshRollback()">بازگردانی آخرین شروع دوباره</button></div></div><div class="card"><h2>شروع انبارداری؛ صفر برای اقلام شمارش‌نشده</h2><p class="hint">اقلامی که هرگز در هیچ شمارش کلی نبوده‌اند و اقلام «دقیق» شمارش‌نشده در این مبنا، با مقدار صفر (شمارش‌شده و ناموجود) به مبنای همان تاریخ اضافه می‌شوند. اقلام «سبک» که قبلاً شمارش شده‌اند از شمارش قبلی خودشان ادامه می‌دهند و صفر نمی‌شوند. مقدارهای شمارش‌شده تغییر نمی‌کنند. اگر قلمی در واقع موجود بوده ولی شمارش نشده، صفر گرفتن آن مانده را منفی می‌کند؛ پس فقط برای اقلام واقعاً ناموجود استفاده کنید. اگر در آن تاریخ هیچ مبنای کلی نباشد، یک مبنای کامل با همه اقلام صفر ساخته می‌شود.</p><div class="form-grid"><div class="field"><label>تاریخ شروع انبارداری</label><input id="rayoZeroDate" data-jalali="1" value=""></div><div class="field"><label>زمان مبنا</label><select id="rayoZeroBoundary"><option value="START">ابتدای روز؛ عملیات همان روز محاسبه شود</option><option value="END">پایان روز؛ عملیات از روز بعد محاسبه شود</option></select></div></div><div class="v1012-actions"><button class="btn btn-primary" onclick="RayoInventoryV10.previewZeroFill()">پیش‌نمایش</button><button class="btn" onclick="RayoInventoryV10.previewZeroFillRollback()">پیش‌نمایش بازگردانی آخرین صفرگذاری</button></div><p id="rayoZeroStatus" role="status"></p></div><div class="card"><h2>بازنشانی شمارش‌ها و انبارگردانی‌ها</h2><p class="hint">فقط اسناد شمارش و موجودی اولیه (کل رایو و محلی) باطل می‌شوند؛ انگار هیچ‌کدام ثبت نشده‌اند. ورود خرید، ضایعات/پرتی و سایر حرکت‌های انبار دست‌نخورده می‌مانند — این کار فقط «مبنا»ی محاسبه موجودی را پاک می‌کند، نه تاریخچه واقعی خرید و مصرف را.</p><button type="button" class="btn btn-danger" onclick="RayoInventoryV10.openResetCounts()">بازنشانی همه شمارش‌ها و افتتاحیه‌ها</button></div>`}
function controlStatus(message){const el=document.getElementById('rayoControlStatus');if(el)el.textContent=message}
function controlAudit(doc,action,details){doc.changeLog=A(doc.changeLog);const row={id:`ICT-${RAYO_API_GATEWAY.createRequestId()}`,action,at:now(),actor:actor(),...details};doc.changeLog.push(row);return row}
async function previewControlChange(){
 if(controlUI.busy)return;controlUI.busy=true;controlUI.plan=null;controlUI.backedUp=false;controlStatus('در حال دریافت نسخه کامل و بررسی تعارض‌ها…');
 try{const before=await controlLoad(),mode=S(document.getElementById('rayoControlMode')?.value),key=S(document.getElementById('rayoControlOpening')?.value),boundary=S(document.getElementById('rayoControlBoundary')?.value);if(!['locations','unified'].includes(mode)||!['START','END'].includes(boundary))throw Error('حالت یا مرز زمانی معتبر نیست');const keys=key?key.split('|').filter(Boolean):[],pool=controlCandidates(before),picked=keys.map(k=>pool.find(c=>c.key===k)),issues=[...new Set(keys.length?picked.flatMap(c=>controlConversionIssues(before,c)):[])];if(new Set(picked.filter(Boolean).map(c=>c.date)).size>1)issues.push('اسناد انتخاب‌شده تاریخ‌های متفاوت دارند؛ هر تاریخ را جداگانه تبدیل کنید');if(issues.length)throw Error(issues.join('؛ '));const candidates=picked,candidate=candidates[0]||null;
  const after=controlClone(before);after.settings=after.settings||{};const previousMode=after.settings.inventoryControlMode??null;if((previousMode||'locations')===mode&&!candidate)throw Error('تغییری انتخاب نشده است');after.settings.inventoryControlMode=mode;
  const changes=[];for(const cand of candidates)for(const r of cand.records){const target=after[cand.collection].find(x=>x.id===r.id),old={inventoryScope:target.inventoryScope??null,baselineBoundary:target.baselineBoundary??null};Object.assign(target,{inventoryScope:'RAYO',baselineBoundary:boundary});changes.push({collection:cand.collection,id:r.id,before:old,after:{inventoryScope:'RAYO',baselineBoundary:boundary}})}
  controlAudit(after,'INVENTORY_CONTROL_CHANGED',{previousMode,nextMode:mode,changes});controlUI.plan={before,after};controlPreviewModal(candidates.flatMap(controlCandidateLines),`حالت: ${mode==='unified'?'کل رایو':'تفکیکی'}${candidate?`؛ ${F(candidates.length,0)} سند؛ تاریخ مبنا ${candidate.date}؛ ${boundary==='START'?'ابتدای روز':'پایان روز'}`:''}`);controlStatus('پیش‌نمایش آماده است؛ هنوز ذخیره نشده است');
 }catch(e){controlStatus(e.message);toastX(e.message,true)}finally{controlUI.busy=false}
}
function controlPreviewModal(lines,description){openModal('پیش‌نمایش دامنه موجودی',`<p class="hint">${E(description)}. مقدارها، شناسه‌ها و محل اصلی حفظ می‌شوند. دادهٔ ناموجود صفر فرض نمی‌شود.</p>${lines.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>شناسه سند</th><th>قلم</th><th>مقدار محفوظ</th><th>واحد</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${E(l.id)}</td><td>${E(ingredient(l.ingredientId)?.name||l.ingredientId)}</td><td>${F(l.quantity,3)}</td><td>${E(l.unit||ingredientUnit(ingredient(l.ingredientId)))}</td></tr>`).join('')}</tbody></table></div>`:''}<button class="btn" onclick="RayoInventoryV10.downloadControlBackup()">دانلود پشتیبان کامل قبل از تغییر</button><p id="rayoControlBackupStatus" role="status"></p><label class="inline-check"><input type="checkbox" id="rayoControlConfirm"> پشتیبان را دریافت کرده‌ام و دامنه و زمان مبنا را تأیید می‌کنم.</label>`,`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" data-control-save onclick="RayoInventoryV10.applyControlChange()">اعمال و بررسی با بازخوانی</button>`)}
function downloadControlBackup(){if(!controlUI.plan)return;downloadInventoryJson(controlUI.plan.before,`inventory-before-scope-${Date.now()}.json`);controlUI.backedUp=true;const el=document.getElementById('rayoControlBackupStatus');if(el)el.textContent='پشتیبان دانلود شد؛ فایل JSON را برای بازیابی نگه دارید.'}
async function applyControlChange(){
 if(controlUI.busy||!controlUI.plan)return;if(!controlUI.backedUp||!document.getElementById('rayoControlConfirm')?.checked)return toastX('دانلود پشتیبان و تأیید مدیر لازم است',true);controlUI.busy=true;document.querySelectorAll('[data-control-save]').forEach(b=>b.disabled=true);
 try{await controlPersist(controlUI.plan.before,controlUI.plan.after);controlUI.plan=null;closeModal();renderView();toastX('تغییر ذخیره و با Load مجدد تأیید شد')}catch(e){toastX(e.message,true)}finally{controlUI.busy=false;document.querySelectorAll('[data-control-save]').forEach(b=>b.disabled=false)}
}
async function previewControlRollback(){
 if(controlUI.busy)return;controlUI.busy=true;controlUI.plan=null;controlUI.backedUp=false;
 try{const before=await controlLoad(),entry=A(before.changeLog).filter(e=>e.action==='INVENTORY_CONTROL_CHANGED'&&!e.revertedAt).at(-1);if(!entry)throw Error('تغییر قابل بازگردانی وجود ندارد');if(A(before.stocktakes).some(s=>wholeScope(s)&&S(s.createdAt)>entry.at)||A(before.periodClosures).some(c=>c.status==='closed'&&S(c.closedAt)>=entry.at))throw Error('پس از این تغییر، شمارش کل یا دوره بسته ثبت شده است؛ بازگردانی نیازمند بررسی اسناد وابسته است');if((before.settings.inventoryControlMode??null)!==entry.nextMode)throw Error('حالت فعلی با تغییر ثبت‌شده سازگار نیست');const after=controlClone(before);if(entry.previousMode===null)delete after.settings.inventoryControlMode;else after.settings.inventoryControlMode=entry.previousMode;const lines=[];
  for(const change of A(entry.changes)){const r=A(after[change.collection]).find(x=>x.id===change.id);if(!r||controlClosed(after,r.date)||r.inventoryScope!==change.after.inventoryScope||r.baselineBoundary!==change.after.baselineBoundary)throw Error('مبنای وابسته تغییر کرده یا دوره بسته است');for(const [k,v]of Object.entries(change.before)){if(v===null)delete r[k];else r[k]=v}lines.push(...controlCandidateLines({collection:change.collection,records:[r]}))}
  after.changeLog.find(e=>e.id===entry.id).revertedAt=now();controlAudit(after,'INVENTORY_CONTROL_ROLLED_BACK',{reverts:entry.id});controlUI.plan={before,after};controlPreviewModal(lines,'بازگردانی دامنه و حالت به مقدار قبل؛ بدون حذف اسناد');
 }catch(e){toastX(e.message,true)}finally{controlUI.busy=false}
}
// Whole count form: one approved document per date + boundary. Entries made over several sessions merge into it;
// counts may be entered out of order, which only warns and re-derives the later counts' variance.
function wholeHelpBody(){return `<div class="hint v1012-help"><p>موجودی واقعی هر قلم را بشمارید. <b>صفر</b> یعنی شمارش شده و ناموجود؛ <b>خانه خالی</b> یعنی این قلم در این شمارش نیست و از شمارش قبلی خودش ادامه می‌دهد.</p><p>برای هر قلم شمارش‌شده: شمارش قبلی + ورود به انبار − مصرف فروش − پرتی و ضایعات = موجودی مورد انتظار؛ اختلاف با عدد شمارش‌شده، مغایرت این دوره است.</p><p><b>نوع شمارش خودکار است:</b> اولین شمارش سیستم (و تاریخی که از قبل شمارش افتتاحیه دارد) <b>افتتاحیه ابتدای روز</b> است و فروش، ورود و پرتی همان روز بعد از آن حساب می‌شود. هر شمارش دیگر <b>پایان روز</b> است، یعنی عملیات همان روز قبل از آن حساب می‌شود؛ شمارش را آخر روز انجام دهید یا تاریخ روز قبل را بزنید.</p><p><b>ثبت در چند نوبت:</b> با انتخاب تاریخ، مقدارهای قبلاً ثبت‌شده همان شمارش در فهرست نمایش داده می‌شوند. اقلام تازه به همان شمارش اضافه می‌شوند؛ تغییر یک مقدار ثبت‌شده پس از هشدار جایگزین آن می‌شود و مقدار قبلی در سابقه می‌ماند. پاک‌کردن مقدار ثبت‌شده، آن قلم را از این شمارش برمی‌دارد.</p><p><b>جمع از چند محل:</b> با دکمه «+» کنار هر قلم، مقدار یخچال یا محل دیگر را جدا وارد کنید تا با مقدار فعلی جمع شود.</p><p><b>ترتیب ثبت آزاد است:</b> شمارشی با تاریخ قبل از شمارش‌های موجود فقط هشدار می‌گیرد و مغایرت شمارش‌های بعدی خودکار بازمحاسبه می‌شود. فروش، ورود یا ضایعاتی هم که بعد از شمارش و با تاریخ قبل از آن ثبت، ویرایش یا باطل شود، هنگام ذخیره خودکار مغایرت همان شمارش‌ها را به‌روز می‌کند.</p></div>`}
function openWholeCountHelp(){openModal('راهنمای شمارش کل رایو',wholeHelpBody(),'<button class="btn" onclick="closeModal()">بستن</button>')}
function openControlHelp(){openModal('راهنمای کنترل تک‌انبار',controlNotice(),'<button class="btn" onclick="closeModal()">بستن</button>')}
function helpIcon(onclick,label){return `<button type="button" class="rayo-help-icon" onclick="${onclick}" title="${E(label)}" aria-label="${E(label)}">؟</button>`}
function controlHelpButton(){return helpIcon('RayoInventoryV10.openControlHelp()','راهنمای کنترل تک‌انبار')}
// One whole count per date; its type is automatic: a date that already has an opening, or the system's very first count, is an opening (start of day); every other count is end of day.
function wholeAutoBoundary(date,doc=inv){const whole=A(doc?.stocktakes).filter(s=>wholeScope(s)&&s.status==='approved'),same=whole.filter(s=>D(s.date)===D(date));if(same.some(s=>controlBoundary(s)==='START'))return 'START';if(same.length)return 'END';return whole.some(s=>cmp(s.date,date)<0)||A(doc?.openingBalances).some(o=>wholeScope(o)&&o.status!=='void'&&cmp(o.date,date)<0)?'END':'START'}
function wholeCountKey(){const date=D(controlUI.wholeDate)||today();return {date,boundary:wholeAutoBoundary(date)}}
function wholeSameRank(doc,date,boundary){const rank=controlRank({date,baselineBoundary:boundary});return A(doc?.stocktakes).filter(s=>wholeScope(s)&&s.status==='approved'&&controlRank(s)===rank)}
function wholeExisting(date,boundary,doc=inv){const out=new Map();for(const s of wholeSameRank(doc,date,boundary))for(const l of A(s.lines))if(!out.has(l.ingredientId))out.set(l.ingredientId,l);return out}
function wholeValueText(v){const n=Q(v);return n===null?'':String(Math.round(n*1e6)/1e6)}
function wholePartsText(parts){return A(parts).length>1?`جمع ${A(parts).map(p=>F(p,3)).join(' + ')}`:''}
function wholeSummaryText(existing,boundary=wholeCountKey().boundary){const kind=boundary==='START'?'نوع: افتتاحیه ابتدای روز (اولین شمارش)':'نوع: پایان روز';return existing.size?`${kind} — ${F(existing.size)} قلم در این تاریخ قبلاً ثبت شده و در فهرست نمایش داده شده است.`:`${kind} — برای این تاریخ هنوز شمارشی ثبت نشده است.`}
// A line fed by prepared items keeps its directly counted part in directActual; the input shows only that part and the prepared share is re-derived on save.
function wholeDirect(line){return line&&N(line.preparedActual)>0?line.directActual:line?.actual}
function wholePrepNote(line){return line&&N(line.preparedActual)>0?`+ ${F(line.preparedActual,3)} از اقلام آماده‌سازی (جمع ${F(line.actual,3)})`:''}
function wholeRow(i,line){const id=E(i.id),value=line?wholeValueText(wholeDirect(line)):'',parts=line&&A(line.countParts).length>1?line.countParts:null;return `<tr data-whole-row data-search="${E(searchNorm(`${i.name} ${i.code||''}`))}"><td>${E(i.name)} <small>${E(i.code||'')}</small> <span class="badge success" data-whole-saved="${id}" ${line?'':'hidden'}>ثبت‌شده</span></td><td>${E(ingredientUnit(i))}</td><td><div class="cu-qty-cell rayo-whole-cell"><input id="cuWhole_${id}" data-whole-count="${id}" value="${E(value)}" ${line?`data-loaded="${E(value)}"`:''} ${parts?`data-parts="${E(JSON.stringify(parts))}"`:''} ${line?.unitEntryDetail?`data-unit-entry="${E(JSON.stringify(line.unitEntryDetail))}"`:''} oninput="RayoInventoryV10.wholeManualEdit(this)" inputmode="decimal" placeholder="شمارش نشده" aria-label="موجودی کل ${E(i.name)}"><button type="button" class="btn btn-sm rayo-whole-add" onclick="RayoInventoryV10.openWholeAdd('${id}')" title="افزودن مقدار از محل دیگر" aria-label="افزودن مقدار از محل دیگر به ${E(i.name)}">+</button>${hasCountingUnits(i)?countingUnitsButton(i.id,'cuWhole_'+i.id):''}</div><small class="muted" data-whole-parts="${id}">${E(wholePartsText(parts))}</small> <small class="muted" data-whole-prep-note="${id}">${E(wholePrepNote(line))}</small></td></tr>`}
// Prepared (composite) items, e.g. burger patties: counted as they are; the save converts them to their ingredients with RayoIngredientMath.preparedItemConversion and keeps stocktakes[].preparedLines.
function wholePreparedItems(){return A(pricing?.preparedItems).filter(p=>p&&p.status!=='غیرفعال').slice().sort((a,b)=>S(a.name).localeCompare(S(b.name),'fa'))}
function wholePreparedExisting(date,boundary,doc=inv){const out=new Map();for(const s of wholeSameRank(doc,date,boundary))for(const l of A(s.preparedLines))if(!out.has(l.preparedItemId))out.set(l.preparedItemId,l);return out}
function wholePrepRow(p,line){const id=E(p.id),value=line?wholeValueText(line.quantity):'',parts=line&&A(line.countParts).length>1?line.countParts:null,multi=A(RayoIngredientMath.countingUnits?.(p,'countUnit')).length>1;return `<tr data-whole-row data-search="${E(searchNorm(`${p.name} ${p.id}`))}"><td>${E(p.name)} <small class="muted">ترکیبی</small> <span class="badge success" data-whole-saved="prep:${id}" ${line?'':'hidden'}>ثبت‌شده</span></td><td>${E(p.countUnit||'')}</td><td><div class="cu-qty-cell rayo-whole-cell"><input id="cuWholePrep_${id}" data-whole-prep="${id}" value="${E(value)}" ${line?`data-loaded="${E(value)}"`:''} ${parts?`data-parts="${E(JSON.stringify(parts))}"`:''} ${line?.unitEntryDetail?`data-unit-entry="${E(JSON.stringify(line.unitEntryDetail))}"`:''} oninput="RayoInventoryV10.wholeManualEdit(this)" inputmode="decimal" placeholder="شمارش نشده" aria-label="شمارش ${E(p.name)}"><button type="button" class="btn btn-sm rayo-whole-add" onclick="RayoInventoryV10.openWholeAdd('${id}','cuWholePrep_${id}')" title="افزودن مقدار از محل دیگر" aria-label="افزودن مقدار از محل دیگر به ${E(p.name)}">+</button>${multi?`<button type="button" class="btn btn-sm cu-trigger" title="ورود با چند واحد" aria-label="ورود با چند واحد" onclick="RayoInventoryV10.openCountingUnitsEntry({preparedItemId:'${id}',inputId:'cuWholePrep_${id}'})">چند واحد</button>`:''}</div><small class="muted" data-whole-parts="prep:${id}">${E(wholePartsText(parts))}</small></td></tr>`}
