function openWholeAdd(id,inputId){const x=document.getElementById(inputId||`cuWhole_${id}`);if(!x)return;const cell=x.closest('.rayo-whole-cell');let box=cell?.querySelector('.rayo-whole-addbox');if(box){box.querySelector('input')?.focus();return}box=document.createElement('span');box.className='rayo-whole-addbox';box.innerHTML=`<input data-whole-add="${E(id)}" inputmode="decimal" placeholder="مقدار محل دیگر" aria-label="مقدار افزودنی"><button type="button" class="btn btn-sm btn-primary">افزودن</button>`;cell.appendChild(box);const input=box.querySelector('input'),apply=()=>applyWholeAdd(id,inputId);box.querySelector('button').onclick=apply;input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();apply()}else if(e.key==='Escape'){e.preventDefault();box.remove();x.focus()}});input.focus()}
