const SHEET_AREAS=[{id:'BAR',name:'بار',locations:['انبار اصلی','بار بالا']},{id:'KITCHEN',name:'آشپزخانه',locations:['انبار اصلی','یخچال آماده‌سازی','یخچال آشپزخانه']},{id:'STORE',name:'انبار و مصرفی',locations:['انبار اصلی']}];
