function sheetGuessArea(category){const c=S(category);if(/تره[\s\u200c]*بار|میوه|سبزی/.test(c))return 'KITCHEN';if(/بار|قهوه|چای|دمنوش|شکلات|سیروپ|پوره|نوشیدنی|قلیون|قلیان/.test(c))return 'BAR';if(/غذا|گوشت|مرغ|ماکیان|ماهی|دریایی|لبنیات|تخم|نان|آرد|خمیر|برنج|غلات|حبوبات|روغن|سس|چاشنی|ادویه|طعم|دسر|قنادی|فریزر|منجمد/.test(c))return 'KITCHEN';return 'STORE'}
