function sheetLayout(){const saved=inv?.settings?.countSheet||{},areas=SHEET_AREAS.map(a=>{const x=A(saved.areas).find(y=>y.id===a.id),locs=A(x?.locations).map(S).filter(Boolean);return {id:a.id,name:S(x?.name)||a.name,locations:locs.length?locs:a.locations}});return {areas,categoryArea:{...(saved.categoryArea||{})},preparedArea:areas.some(a=>a.id===saved.preparedArea)?saved.preparedArea:'KITCHEN'}}
function sheetAreaOf(layout,category){const v=layout.categoryArea[category];return layout.areas.some(a=>a.id===v)?v:sheetGuessArea(category)}
function sheetAreaSelect(attr,value,areas){return `<select ${attr}>${areas.map(a=>`<option value="${a.id}" ${a.id===value?'selected':''}>${E(a.name)}</option>`).join('')}</select>`}
function openCountSheet(){const layout=sheetLayout(),cats=sheetCategories(),count=c=>controlItems().filter(i=>sheetCategory(i)===c).length,preps=wholePreparedItems().length;
 const body=`<p class="hint">برگهٔ خالی برای شمارش دستی: اقلام بر اساس بخش (بار، آشپزخانه، انبار) و گروه دسته‌بندی می‌شوند و برای هر محل نگهداری یک ستون دارند. موجودی سیستم در برگه نمی‌آید. مقدارهای ستون‌ها را جمع بزنید و در فرم شمارش وارد کنید؛ برای ثبت جدای هر محل از دکمهٔ «+» کنار هر قلم استفاده کنید.</p><div class="form-grid">${layout.areas.map(a=>`<div class="field"><label>محل‌های ${E(a.name)} (با «،» جدا کنید)</label><input data-sheet-locs="${a.id}" value="${E(a.locations.join('، '))}"></div>`).join('')}${preps?`<div class="field"><label>بخش اقلام آماده‌سازی‌شده (${F(preps)} قلم)</label>${sheetAreaSelect('id="rayoSheetPrepArea"',layout.preparedArea,layout.areas)}</div>`:''}</div><div class="table-wrap" style="max-height:45vh"><table class="data-table"><thead><tr><th>گروه کالا</th><th>تعداد قلم</th><th>بخش در برگه</th></tr></thead><tbody>${cats.map(c=>`<tr><td>${E(c)}</td><td>${F(count(c))}</td><td>${sheetAreaSelect(`data-sheet-cat="${E(c)}"`,sheetAreaOf(layout,c),layout.areas)}</td></tr>`).join('')}</tbody></table></div><p id="rayoSheetStatus" role="status"></p>`;
 openModal('برگهٔ انبارگردانی',body,'<button class="btn" onclick="closeModal()">بستن</button><button class="btn" onclick="RayoInventoryV10.saveCountSheetLayout()">ذخیرهٔ چیدمان</button><button class="btn" onclick="RayoInventoryV10.exportCountSheet()">خروجی اکسل</button><button class="btn btn-primary" onclick="RayoInventoryV10.printCountSheet()">چاپ</button>')}
