   ws['!ref']=XLSX.utils.encode_range({s:{r:0,c:0},e:{r:rows.length-1,c:h.length-1}});ws['!merges']=merges;ws['!cols']=[{wch:5},{wch:10},{wch:34},{wch:10},{wch:18},...a.locations.map(()=>({wch:14})),{wch:10},{wch:18}];
