function locationForSection(section,person){if(person?.inventoryLocationId&&locationBy(person.inventoryLocationId))return person.inventoryLocationId;const q=S(section||person?.section||person?.mainSection||person?.subSection).replace(/\s+/g,'');if(!q)return'';const l=activeLocations().find(x=>{const a=S(x.section||x.name).replace(/\s+/g,'');return a&&((a===q)||a.includes(q)||q.includes(a))});return l?.id||''}
function wasteShiftRows(date){const rows=[];for(const x of A(hr?.shiftRecords).filter(x=>S(x.date)===S(date)&&!['لغوشده','مرخصی','غیبت'].includes(S(x.status))))rows.push({personnelId:x.personnelId,shift:x.shift,section:x.section||x.subSection||''});for(const plan of A(hr?.monthlyPlans)){for(const [key,ids] of Object.entries(plan.cells||{})){const parts=S(key).split('|');if(parts.length!==3||parts[0]!==date)continue;let section='';try{section=decodeURIComponent((parts[1].split('~')[0]||''))}catch(_){section=parts[1].split('~')[0]||''}for(const pid of A(ids))if(!rows.some(r=>r.personnelId===pid&&r.shift===parts[2]))rows.push({personnelId:pid,shift:parts[2],section})}}const u=new Map;for(const r of rows)u.set(`${r.personnelId}|${r.shift}`,r);return [...u.values()]}
function wasteDeclarationStatus(date=today()){const people=A(hr?.personnel),decl=A(inv?.wasteShiftDeclarations).filter(x=>x.date===date),expected=[];for(const sh of wasteShiftRows(date)){const p=people.find(x=>x.id===sh.personnelId),pm=p?.userAccess?.permissions||{};if(!p||p.status!=='فعال'||(!pm.inventoryWaste&&!pm.inventoryConsumption))continue;const locationId=locationForSection(sh.section,p);if(!locationId)continue;const d=decl.find(x=>x.personnelId===p.id&&x.shift===sh.shift&&x.locationId===locationId);expected.push({personnelId:p.id,personnelName:p.name,shift:sh.shift,section:sh.section,locationId,declaration:d||null,status:d?'ثبت‌شده':'ثبت‌نشده'})}return{date,expected,submitted:expected.filter(x=>x.declaration).length,missing:expected.filter(x=>!x.declaration)}}
function wasteShiftDeclarationsTable(){const rows=A(inv.wasteShiftDeclarations).slice().sort((a,b)=>cmp(b.date,a.date)||S(b.createdAt).localeCompare(S(a.createdAt))).slice(0,150),st=wasteDeclarationStatus(today());return `<div class="card"><div class="section-head"><div><h2>کنترل جمع‌بندی امروز</h2><p class="muted">فقط پرسنل برنامه‌ریزی‌شده‌ای که دسترسی ثبت ضایعات/مصرف دارند انتظار می‌رود جمع‌بندی ثبت کنند.</p></div></div>${st.expected.length?`<div class="grid grid-3"><div class="kpi"><div class="label">مورد انتظار امروز</div><div class="value">${F(st.expected.length)}</div></div><div class="kpi"><div class="label">ثبت‌شده</div><div class="value positive">${F(st.submitted)}</div></div><div class="kpi"><div class="label">ثبت‌نشده</div><div class="value danger-text">${F(st.missing.length)}</div></div></div>${st.missing.length?`<div class="hint" style="margin-top:10px"><b>ثبت‌نشده:</b> ${st.missing.map(x=>`${E(x.personnelName)} — ${E(x.shift)} — ${E(locationName(x.locationId))}`).join(' | ')}</div>`:''}`:'<div class="hint">برای امروز برنامه شیفت قابل تطبیق با کاربران مجاز پیدا نشد؛ بنابراین هشدار ثبت‌نشده تولید نمی‌شود.</div>'}</div><div class="card"><div class="section-head"><div><h2>جمع‌بندی پایان شیفت پرسنل</h2><p class="muted">ثبت «بدون مورد» باعث می‌شود شیفت بدون گزارش، با شیفتی که اصلاً چیزی ثبت نکرده اشتباه نشود.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>شیفت</th><th>سکشن/محل</th><th>پرسنل</th><th>وضعیت اعلامی</th><th>رویدادهای ثبت‌شده</th><th>زمان ثبت</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.date)}</td><td>${E(r.shift||'—')}</td><td>${E(locationName(r.locationId))}</td><td>${E(r.personnelName||personnelName(r.personnelId))}</td><td>${r.declarationType==='NO_EVENT'?'<span class="badge success">بدون مورد</span>':'<span class="badge warn">دارای رویداد</span>'}</td><td>${F(r.eventCount)}</td><td>${E(r.localTime||r.createdAt||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">جمع‌بندی پایان شیفتی ثبت نشده است.</td></tr>'}</tbody></table></div></div>`}
/* ---------- Waste form: section → person → item (menu / ingredient / tableware & equipment) → optional fine ----------
   The section narrows the people and puts the items that section has recorded before at the top; any item is still reachable by search.
   Tableware and equipment come from the assets module and are saved there as an incident (status «جدید») for the assets review flow.
   A fine is an approved penalty in HR whose apply date decides the payroll month. */
const wasteUI={section:'',type:'menu',category:'',q:''};
function wastePersonSection(p){return S(p?.section)||S(p?.personnelGroup)}
function wasteSections(){return [...new Set(activePersonnelRows().map(wastePersonSection).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fa'))}
function wasteSectionMatch(a,b){a=S(a);b=S(b);return !!a&&!!b&&(a===b||a.includes(b)||b.includes(a))}
function wasteAssets(){return A(window.__rayoWasteAssets?.assets).filter(a=>a.isArchived!==true&&!['اسقاط‌شده','غیرفعال'].includes(S(a.status)))}
function wasteRows(type){return type==='menu'?A(pricing.menuItems).filter(i=>i.status!=='غیرفعال'):type==='asset'?wasteAssets():A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK')}
function wasteUnit(type,x){return type==='menu'?'عدد':type==='asset'?S(x?.unit)||'عدد':ingredientUnit(x)}
function wasteHistory(type,section){const map=new Map;if(!section)return map;const people=new Map(A(hr?.personnel).map(p=>[p.id,p]));for(const r of [...A(inv.wasteRecords),...A(inv.consumptionRecords)]){if(r.isArchived===true||S(r.type||'ingredient')!==type)continue;const p=people.get(r.responsiblePersonnelId)||people.get(r.reportedByPersonnelId);if(p&&wasteSectionMatch(wastePersonSection(p),section))map.set(r.itemId,(map.get(r.itemId)||0)+1)}return map}
function wasteItemOptions(){const type=wasteUI.type,section=wasteUI.section,q=S(wasteUI.q).toLowerCase(),hist=wasteHistory(type,section),person=A(hr?.personnel).find(p=>p.id===document.getElementById('v10EvPerson')?.value),group=S(person?.personnelGroup),rows=wasteRows(type).filter(x=>(!wasteUI.category||S(x.category)===wasteUI.category)&&(!q||S(x.name).toLowerCase().includes(q))),score=x=>(hist.get(x.id)||0)*10+(type==='asset'&&(wasteSectionMatch(x.location,section)||wasteSectionMatch(x.location,group))?5:0);if(type==='asset'&&!window.__rayoWasteAssets)return '<option value="" disabled>در حال دریافت فهرست اموال…</option>';return rows.map(x=>({x,sc:score(x)})).sort((a,b)=>b.sc-a.sc||S(a.x.name).localeCompare(S(b.x.name),'fa')).map(({x,sc})=>`<option value="${E(x.id)}">${sc>0?'★ ':''}${E(x.name)} — ${E(wasteUnit(type,x))}</option>`).join('')||'<option value="" disabled>موردی پیدا نشد</option>'}
function wasteCategoryOptions(){const cats=[...new Set(wasteRows(wasteUI.type).map(x=>S(x.category)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fa'));if(!cats.includes(wasteUI.category))wasteUI.category='';return '<option value="">همه دسته‌ها</option>'+cats.map(c=>`<option ${c===wasteUI.category?'selected':''}>${E(c)}</option>`).join('')}
function wastePeopleOptions(selected=''){const sec=wasteUI.section,rows=activePersonnelRows().slice().sort((a,b)=>(wasteSectionMatch(wastePersonSection(b),sec)-wasteSectionMatch(wastePersonSection(a),sec))||S(a.name).localeCompare(S(b.name),'fa'));return '<option value="">—</option>'+rows.map(p=>`<option value="${E(p.id)}" ${p.id===selected?'selected':''}>${E(p.name)}${sec&&!wasteSectionMatch(wastePersonSection(p),sec)?' (سایر سکشن‌ها)':''}</option>`).join('')}
function wasteFormHtml(one,locs){if(wasteUI.type==='asset')setTimeout(wasteLoadAssets,0);return `<div class="form-grid waste-form"><div class="field"><label>تاریخ رخداد</label><input id="v10EvDate" data-jalali="1" value="${E(today())}"></div><div class="field"><label>نوع رویداد</label><select id="v10EvEventType" data-no-placeholder="1">${Object.entries(EVENT_LABELS).map(([k,l])=>`<option value="${k}">${E(l)}</option>`).join('')}</select></div><div class="field"><label>شیفت</label><select id="v10EvShift" data-no-placeholder="1"><option>صبح</option><option>عصر</option><option>دو شیفت</option></select></div><div class="field"><label>سکشن</label><select id="v10EvSection" data-no-placeholder="1" onchange="RayoInventoryV10.wasteSection(this.value)"><option value="">همه سکشن‌ها</option>${wasteSections().map(x=>`<option ${x===wasteUI.section?'selected':''}>${E(x)}</option>`).join('')}</select></div><div class="field"><label>فرد مرتبط</label><select id="v10EvPerson" data-no-placeholder="1" onchange="RayoInventoryV10.wastePerson()">${wastePeopleOptions()}</select></div><div class="field"><label>نوع مورد</label><select id="v10EvItemType" data-no-placeholder="1" onchange="RayoInventoryV10.eventItemType()"><option value="menu" ${wasteUI.type==='menu'?'selected':''}>آیتم منو</option><option value="ingredient" ${wasteUI.type==='ingredient'?'selected':''}>ماده اولیه / اقلام انبار</option><option value="asset" ${wasteUI.type==='asset'?'selected':''}>ظروف و تجهیزات (اموال)</option></select></div><div class="field full waste-item-picker"><label for="v10EvItem">مورد <small class="muted">★ = مواردی که این سکشن قبلاً ثبت کرده است؛ بقیه با جست‌وجو یا دسته</small></label><div class="waste-item-filters"><input id="v10EvSearch" type="search" placeholder="جست‌وجوی نام" autocomplete="off" value="${E(wasteUI.q)}" oninput="RayoInventoryV10.wasteSearch(this.value)"><select id="v10EvCategory" data-no-placeholder="1" onchange="RayoInventoryV10.wasteCategory(this.value)">${wasteCategoryOptions()}</select></div><select id="v10EvItem" size="7" data-no-placeholder="1" onchange="RayoInventoryV10.wasteValue()">${wasteItemOptions()}</select></div>${one?`<input type="hidden" id="v10EvLoc" value="${E(inv.settings.mainLocationId)}">`:`<div class="field"><label>محل انبار</label><select id="v10EvLoc">${optionRows(locs,inv.settings.mainLocationId)}</select></div>`}<div class="field"><label>مقدار / تعداد <small class="muted" id="v10EvUnit"></small></label><div class="cu-qty-cell"><input id="v10EvQty" type="number" step="0.001" oninput="RayoInventoryV10.wasteValue()"><button type="button" class="btn btn-sm cu-trigger" id="v10EvUnitsBtn" ${wasteUI.type==='ingredient'?'':'hidden'} title="ورود با چند واحد" aria-label="ورود با چند واحد" onclick="RayoInventoryV10.openEventUnits()">چند واحد</button></div></div><div class="field"><label>ارزش برآوردی</label><div class="waste-value" id="v10EvValue">—</div></div><div class="field"><label>شماره فیش سپیدز</label><input id="v10EvInvoice" placeholder="اختیاری"></div><div class="field"><label>علت</label><input id="v10EvReason" placeholder="مثلاً شکستن هنگام جمع‌آوری، سوختن، اشتباه سفارش"></div><div class="field full"><label>توضیحات</label><textarea id="v10EvNotes" rows="2"></textarea></div><div class="full waste-fine"><label class="inline-check"><input type="checkbox" id="v10EvFine" onchange="RayoInventoryV10.wasteFineToggle()"> ثبت جریمه برای فرد مرتبط</label><div id="v10EvFineBox" class="waste-fine-box" hidden><div class="field"><label for="v10EvFineAmount">مبلغ جریمه (تومان) <small class="muted" id="v10EvFineHint"></small></label><input id="v10EvFineAmount" type="text" inputmode="numeric" oninput="this.dataset.touched='1'"></div><div class="field"><label for="v10EvFineDate">تاریخ اعمال در حقوق</label><input id="v10EvFineDate" data-jalali="1" value="${E(today())}"><small class="muted">جریمه در حقوق ماهِ همین تاریخ کسر می‌شود.</small></div></div></div><div class="full"><button class="btn btn-primary" onclick="RayoInventoryV10.saveEvent()">ثبت رویداد</button></div></div>`}
function wasteRefreshItems(){const sel=document.getElementById('v10EvItem'),cat=document.getElementById('v10EvCategory');if(cat)cat.innerHTML=wasteCategoryOptions();if(sel){const keep=sel.value;sel.innerHTML=wasteItemOptions();if([...sel.options].some(o=>o.value===keep))sel.value=keep}const btn=document.getElementById('v10EvUnitsBtn');if(btn)btn.hidden=wasteUI.type!=='ingredient';wasteValue()}
function wasteSection(v){wasteUI.section=S(v);const per=document.getElementById('v10EvPerson');if(per){const keep=per.value;per.innerHTML=wastePeopleOptions(keep)}wasteRefreshItems()}
function wastePerson(){const p=A(hr?.personnel).find(x=>x.id===document.getElementById('v10EvPerson')?.value),sec=wastePersonSection(p);if(sec&&!wasteUI.section){const el=document.getElementById('v10EvSection');if(el&&[...el.options].some(o=>o.value===sec))el.value=sec;wasteSection(sec)}else wasteRefreshItems()}
async function wasteLoadAssets(){if(window.__rayoWasteAssets||window.__rayoWasteAssetsLoading)return;window.__rayoWasteAssetsLoading=true;try{window.__rayoWasteAssets=await RAYO_API_GATEWAY.loadModule('assets')}catch(e){toastX('فهرست اموال دریافت نشد: '+(e.message||''),true)}finally{window.__rayoWasteAssetsLoading=false}if(wasteUI.type==='asset')wasteRefreshItems()}
function eventItemType(){wasteUI.type=S(document.getElementById('v10EvItemType')?.value)||'menu';wasteUI.category='';if(wasteUI.type==='asset')wasteLoadAssets();wasteRefreshItems()}
function wasteSearch(v){wasteUI.q=S(v);clearTimeout(wasteUI.timer);wasteUI.timer=setTimeout(wasteRefreshItems,150)}
function wasteCategory(v){wasteUI.category=S(v);wasteRefreshItems()}
/* Estimated value: ingredient = quantity × gross unit cost; menu item = recipe cost at the event date; asset = quantity × unit value. 0 = unknown. */
function wasteEstimate(type,id,qty,date){if(!(qty>0)||!id)return 0;if(type==='asset'){const a=wasteAssets().find(x=>x.id===id);return qty*N(a?.baseUnitPriceToman||a?.valuationBaseUnitPriceToman||a?.purchaseCost)}if(type==='menu'){try{return recipeAt(id,date).reduce((sum,r)=>{const i=ingredient(r.ingredientId);return sum+N(RayoIngredientMath.grossQuantity(i,r,qty))*N(RayoIngredientMath.grossCost(i,pricing))},0)}catch(_){return 0}}return qty*N(RayoIngredientMath.grossCost(ingredient(id),pricing))}
function wasteValue(){const type=wasteUI.type,id=document.getElementById('v10EvItem')?.value,qty=N(document.getElementById('v10EvQty')?.value),row=wasteRows(type).find(x=>x.id===id),unit=document.getElementById('v10EvUnit');if(unit)unit.textContent=row?`(واحد: ${wasteUnit(type,row)})`:'';const v=Math.round(wasteEstimate(type,id,qty,D(document.getElementById('v10EvDate')?.value)||today())),box=document.getElementById('v10EvValue');if(box)box.textContent=v>0?`${F(v)} تومان`:(id&&qty>0?'نامشخص (قیمت ثبت نشده)':'—');const fine=document.getElementById('v10EvFineAmount'),hint=document.getElementById('v10EvFineHint');if(hint)hint.textContent=v>0?`پیشنهاد: ${F(Math.ceil(v/1000)*1000)}`:'';if(fine&&fine.dataset.touched!=='1')fine.value=v>0?String(Math.ceil(v/1000)*1000):''}
function wasteFineToggle(){const on=!!document.getElementById('v10EvFine')?.checked,box=document.getElementById('v10EvFineBox');if(box)box.hidden=!on;if(on){wasteValue();window.RayoJalali?.mark?.()}}
