function wasteTrendHtml(rows){const max=Math.max(1,...A(rows).map(x=>N(x.wastePct)));return `<div class="table-wrap"><table class="data-table"><thead><tr><th>ماه</th><th>مبلغ ضایعات</th><th>٪ از فروش</th><th>٪ از کل مصرف مواد</th><th>٪ از مصرف استاندارد</th><th>روند</th></tr></thead><tbody>${A(rows).map(x=>`<tr><td>${E(x.key)}</td><td>${M(x.waste)}</td><td><b>${x.salesAvailable?`${F(x.wastePct,2)}٪`:'—'}</b></td><td>${(x.standard+x.waste+x.auth)>0?`${F(x.wasteShareOfMaterialOut,2)}٪`:'—'}</td><td>${x.standard>0?`${F(x.wastePctStandard,2)}٪`:'—'}</td><td><div style="min-width:120px;background:#eef2f3;border-radius:999px;height:9px;overflow:hidden"><div style="width:${Math.min(100,N(x.wastePct)/max*100)}%;height:100%;background:var(--rayo,#315d68)"></div></div></td></tr>`).join('')}</tbody></table></div>`}
function wasteQuantityHtml(rows){return A(rows).length?A(rows).map(x=>`<span class="badge" style="margin-left:6px">${F(x.quantity,3)} ${E(x.unit)}</span>`).join(''):'—'}
function costPane(){if(!ui.costFrom){const t=today();ui.costFrom=t?`${t.slice(0,8)}01`:'';ui.costTo=t}const p=periodMetrics(ui.costFrom,ui.costTo),short=p.lines.filter(x=>x.unexplained>0).sort((a,b)=>b.unexplained-a.unexplained).slice(0,20),trend=wasteTrend(6);return `<div class="card"><div class="toolbar"><div class="field"><label>از تاریخ</label><input data-jalali="1" value="${E(ui.costFrom)}" onchange="RayoInventoryV10.setCostFrom(this.value)"></div><div class="field"><label>تا تاریخ</label><input data-jalali="1" value="${E(ui.costTo)}" onchange="RayoInventoryV10.setCostTo(this.value)"></div><button class="btn btn-primary" onclick="RayoInventoryV10.closePeriod()">بستن دوره / Snapshot</button></div><div class="hint">بهای واقعی مواد زمانی بیشترین اعتبار را دارد که شمارش پایان دوره پوشش کامل داشته باشد. پوشش فعلی: <b>${F(p.coverage,1)}٪</b>. مبنای فروش نسبت‌ها: <b>${E(p.salesSource)}</b>.</div></div><div class="grid grid-4"><div class="card kpi"><div class="label">موجودی ابتدای دوره</div><div class="value">${F(p.openingValue)}</div><div class="sub">تومان</div></div><div class="card kpi"><div class="label">خرید خالص دوره</div><div class="value">${F(p.purchases)}</div><div class="sub">تومان</div></div><div class="card kpi"><div class="label">بهای استاندارد مواد فروش</div><div class="value">${F(p.standard)}</div><div class="sub">${F(p.standardPct,1)}٪ فروش</div></div><div class="card kpi"><div class="label">بهای واقعی/تقریبی مواد</div><div class="value">${F(p.actualCogs)}</div><div class="sub">${F(p.actualPct,1)}٪ فروش</div></div><div class="card kpi"><div class="label">ضایعات ثبت‌شده</div><div class="value">${F(p.waste)}</div><div class="sub">${F(p.wastePct,2)}٪ فروش | ${F(p.wastePctStandard,2)}٪ مصرف</div></div><div class="card kpi"><div class="label">حجم ضایعات</div><div class="value">${F(p.wasteEventCount)}</div><div class="sub">رویداد | ${wasteQuantityHtml(p.wasteQuantities)}</div></div><div class="card kpi"><div class="label">مفقودی ثبت‌شده</div><div class="value">${F(p.missing)}</div><div class="sub">تومان / جدا از ضایعات</div></div><div class="card kpi"><div class="label">مغایرت توضیح‌داده‌نشده</div><div class="value">${F(p.unexplained)}</div><div class="sub">${F(p.variancePct,1)}٪ فروش</div></div></div><div class="card"><div class="section-head"><div><h2>روند ضایعات — ۶ ماه اخیر</h2><p class="muted">برای مقایسه تورم‌پذیر، درصد ضایعات نسبت به فروش و مصرف مواد کنار مبلغ نمایش داده می‌شود.</p></div></div>${wasteTrendHtml(trend)}</div><div class="grid grid-2"><div class="card"><div class="section-head"><h2>تفکیک مقدار از اثر قیمت</h2></div><div class="table-wrap"><table class="data-table"><tbody><tr><th>فروش خالص ثبت‌شده</th><td>${M(p.sales)}</td></tr><tr><th>مبنای فروش</th><td>${E(p.salesSource)}</td></tr><tr><th>کالای در دسترس</th><td>${M(p.available)}</td></tr><tr><th>موجودی پایان استفاده‌شده</th><td>${M(p.closingValue)}</td></tr><tr><th>اثر تغییر قیمت خرید دوره</th><td>${M(p.priceEffect)}</td></tr><tr><th>مصرف مجاز</th><td>${M(p.auth)}</td></tr><tr><th>مفقودی ثبت‌شده</th><td>${M(p.missing)}</td></tr><tr><th>مغایرت فیزیکی/مصرف توضیح‌داده‌نشده</th><td>${M(p.unexplained)}</td></tr></tbody></table></div></div><div class="card"><div class="section-head"><h2>Top مواد نیازمند بررسی</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ماده</th><th>مصرف استاندارد</th><th>ضایعات</th><th>مصرف مجاز</th><th>اختلاف</th><th></th></tr></thead><tbody>${short.map(x=>`<tr><td>${E(x.name)}</td><td>${F(x.stdQty,3)}</td><td>${F(x.wasteQty,3)}</td><td>${F(x.authQty,3)}</td><td>${M(x.unexplained)}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.drill('${x.ingredientId}','')">Drill-down</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">مورد قابل توجهی وجود ندارد.</td></tr>'}</tbody></table></div></div></div>${helpCard('بهای مواد و بستن دوره',['روش ارزش‌گذاری میانگین موزون است.','افت استاندارد در مصرف ناخالص فروش لحاظ شده است؛ فقط ضایعات غیرعادی را جداگانه ثبت کنید. مقدار ضایعات ماده، مقدار ناخالص موجودی است.','درصد ضایعات هم نسبت به فروش و هم نسبت به مصرف استاندارد مواد نمایش داده می‌شود.','برای بهای واقعی مواد قابل اتکا، شمارش واقعی پایان دوره باید پوشش بالا داشته باشد.','بستن دوره Snapshot محاسبات را نگه می‌دارد تا گزارش گذشته با تغییرات آینده جابه‌جا نشود.'])}`}
function historyPane(){const rows=A(inv.stocktakes).filter(st=>st.status==='approved'&&(unifiedMode()?wholeScope(st):!wholeScope(st))).flatMap(st=>A(st.lines).map(l=>({st,l}))).sort((a,b)=>cmp(b.st.date,a.st.date)).slice(0,1000);return `<div class="card"><div class="section-head"><h2>روند مغایرت و شمارش‌های تأییدشده</h2></div><div class="toolbar"><div class="field"><label>Location</label><select onchange="RayoInventoryV10.setHistoryLocation(this.value)"><option value="">همه</option>${optionRows(activeLocations(),ui.historyLocation)}</select></div><div class="field"><label>ماده</label>${searchablePicker('rayoHistoryIng',[{id:'',name:'همه مواد',code:''},...A(pricing.ingredients).filter(i=>i.status!=='غیرفعال'&&i.itemType!=='NON_STOCK').slice().sort((a,b)=>S(a.name).localeCompare(S(b.name),'fa'))],ui.historyIngredient,x=>x.id?`${x.code||''} | ${x.name}`:x.name,x=>`${x.name||''} ${x.code||''}`,'نام یا کد ماده — خالی برای همه','RayoInventoryV10.setHistoryIngredient(document.getElementById(\'rayoHistoryIng\').value)')}</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>Location</th><th>ماده</th><th>انتظار</th><th>واقعی</th><th>مغایرت</th><th>ارزش مغایرت</th><th>وضعیت</th><th></th></tr></thead><tbody>${rows.filter(x=>(!ui.historyLocation||x.st.locationId===ui.historyLocation)&&(!ui.historyIngredient||x.l.ingredientId===ui.historyIngredient)).map(x=>`<tr><td>${E(x.st.date)}</td><td>${E(wholeScope(x.st)?'کل رایو':locationName(x.st.locationId))}</td><td>${E(ingredient(x.l.ingredientId)?.name||'—')}</td><td>${F(x.l.expected,3)} ${E(ingredientUnit(ingredient(x.l.ingredientId)))}</td><td>${F(x.l.actual,3)} ${E(ingredientUnit(ingredient(x.l.ingredientId)))}</td><td>${F(x.l.variance,3)} ${E(ingredientUnit(ingredient(x.l.ingredientId)))}</td><td>${M(x.l.variance===null||x.l.unitCost===null?null:N(x.l.variance)*N(x.l.unitCost))}</td><td>${x.l.variance===null?'<span class="badge warn">شمارش اولیه / مبنای ناقص</span>':Math.abs(N(x.l.variancePercent))>N(x.l.tolerancePercent||5)?'<span class="badge warn">نیازمند بررسی</span>':'<span class="badge success">عادی</span>'}</td><td><button class="btn btn-sm" onclick="RayoInventoryV10.drill('${x.l.ingredientId}','${x.st.locationId}')">گردش</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">رکوردی وجود ندارد.</td></tr>'}</tbody></table></div></div>`}
function renderPaneOnly(tab){if(!loaded||!inv||!pricing){setTimeout(async()=>{await ensure();try{renderView()}catch(_){}},0);return '<div class="card empty">در حال آماده‌سازی اطلاعات انبار و قیمت‌گذاری…</div>'}return tab==='overview'?overview():tab==='valuation'?valuationPane():tab==='locations'?locationsPane():tab==='transfer'?transferPane():tab==='waste'?wastePane():tab==='stock'?stockPane():tab==='cost'?costPane():historyPane()}
function renderCustom(tab){return pageHead('انبار و کنترل مصرف','کنترل موجودی، مصرف، ضایعات، شمارش و بهای مواد')+nav()+renderPaneOnly(tab)}
function wrapView(){if(typeof views==='undefined'||!views.inventory)return;if(window.__RAYO_INVENTORY_CORE_12){views.inventory.__v10=true;return}if(views.inventory.__v10)return;baseView=views.inventory;const w=function(){const q=new URLSearchParams(location.search).get('tab');if(TABS.includes(q)&&window.ops)window.ops.tab=q;if(!loaded){setTimeout(async()=>{await ensure();try{renderView()}catch(_){}},0);return pageHead('انبار، Cost Control و مغایرت','')+'<div class="card empty">در حال آماده‌سازی کنترل انبار…</div>'}const tab=window.ops?.tab||'overview';if(['overview','valuation','locations','transfer','waste','stock','cost','history'].includes(tab))return renderCustom(tab);let html=baseView();html=html.replace(/<div class="ops-tabs">[\s\S]*?<\/div>/,nav());return html};w.__v10=true;views.inventory=w}
function openModal(title,body,foot=''){const t=document.getElementById('modalTitle'),b=document.getElementById('modalBody'),f=document.getElementById('modalFoot'),m=document.getElementById('modalBackdrop');if(!t||!b||!f||!m)return;t.textContent=title;b.innerHTML=body;f.innerHTML=foot;m.classList.add('open');setTimeout(()=>window.RayoJalali?.mark?.(),0)}
async function saveBaseSettings(){inv.settings.mainLocationId=document.getElementById('v10MainLoc').value;inv.settings.defaultSalesLocationId=document.getElementById('v10DefSaleLoc').value;await saveInv('ویرایش تنظیمات Location');renderView()}
function editLocation(id=''){const l=id?A(inv.locations).find(x=>x.id===id):{code:'',name:'',type:'section',section:'',isActive:true,notes:''};openModal(id?'ویرایش Location':'Location جدید',`<div class="form-grid"><div class="field"><label>کد</label><input id="v10LocCode" value="${E(l.code)}"></div><div class="field"><label>نام</label><input id="v10LocName" value="${E(l.name)}"></div><div class="field"><label>نوع</label><select id="v10LocType"><option value="main" ${l.type==='main'?'selected':''}>انبار اصلی</option><option value="section" ${l.type!=='main'?'selected':''}>مصرفی/سکشن</option></select></div><div class="field"><label>سکشن</label><input id="v10LocSection" value="${E(l.section||'')}"></div><div class="field"><label>فعال</label><select id="v10LocActive"><option value="1" ${l.isActive!==false?'selected':''}>بله</option><option value="0" ${l.isActive===false?'selected':''}>خیر</option></select></div><div class="field full"><label>توضیحات</label><textarea id="v10LocNotes">${E(l.notes||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="RayoInventoryV10.saveLocation('${E(id)}')">ذخیره</button>`)}
async function saveLocation(id=''){const code=S(document.getElementById('v10LocCode').value),name=S(document.getElementById('v10LocName').value);if(!code||!name)return toastX('کد و نام Location الزامی است',true);let l=id?A(inv.locations).find(x=>x.id===id):null;if(!l){l={id:uid('LOC',inv.locations)};inv.locations.push(l)}Object.assign(l,{code,name,type:document.getElementById('v10LocType').value,section:S(document.getElementById('v10LocSection').value),isActive:document.getElementById('v10LocActive').value==='1',notes:S(document.getElementById('v10LocNotes').value),updatedAt:now()});await saveInv(id?'ویرایش Location':'افزودن Location');closeModal();renderView()}
